                [grid[r + k][c + i] for i in range(len(seq))] == seq
                for k in (1, 2)
            ):
                colors, key_r, key_c = seq, r, c
                break
        if colors:
            break

    if not colors or 1 not in colors:
        return grid

    # The largest connected component of 1s is the template.
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 1 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                x, y = stack.pop()
                comp.append((x, y))
                for a, b in ((x-1, y), (x+1, y), (x, y-1), (x, y+1)):
                    if 0 <= a < h and 0 <= b < w and grid[a][b] == 1 and (a, b) not in seen:
                        seen.add((a, b))
                        stack.append((a, b))
            components.append(comp)

    shape = max(components, key=len)
    top = min(r for r, c in shape)
    left = min(c for r, c in shape)
    offsets = [(r-top, c-left) for r, c in shape]
    step = max(dr for dr, dc in offsets) + 1

    out = [[0] * w for _ in range(h)]
    anchor = colors.index(1)
    for i, color in enumerate(colors):
        shift = (i - anchor) * step
        for dr, dc in offsets:
            rr, cc = top + shift + dr, left + dc
            if 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = color
    return out
